        {
         "mota": "testua",
         "html": "<math display=\"block\"><mrow><mi>f</mi><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> jarraitua </mtext><mspace width=\"0.333em\"></mspace></mrow><mo>⇔</mo><mi>x</mi><mo>+</mo><mi>y</mi><mo>≠</mo><mn>0</mn><mo>;</mo><mspace width=\"1.0em\"></mspace><mi>x</mi><mo>+</mo><mi>y</mi><mo>=</mo><mn>0</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> zuzen OSOAN ez-jarraitua </mtext><mspace width=\"0.333em\"></mspace></mrow></mrow></math>"
        }
